#include <iostream>

class MyClass {
private:
    int value;
public:
    MyClass(int v = 0) : value(v) {}
    // Prefix increment operator
    MyClass& operator++() {
        ++value;
        return *this;
    }
    // Postfix increment operator
    MyClass operator++(int) {
        MyClass temp = *this;
        ++(*this);
        return temp;
    }
    int getValue() const { return value; }
};

int main() {
    MyClass obj1(5);
    MyClass obj2 = ++obj1;
    std::cout << obj1.getValue() << " ";
    std::cout << obj2.getValue() << std::endl;

    MyClass obj3(10);
    MyClass obj4 = obj3++;
    std::cout << obj3.getValue() << " ";
    std::cout << obj4.getValue();

    return 0;
}
```

